$port=3000;$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Any,$port);$l.Start();while($true){$c=$l.AcceptTcpClient();$s=$c.GetStream();$r=New-Object IO.StreamReader($s);$req=$r.ReadLine();if(!$req){$c.Close();continue};$p=[Uri]::UnescapeDataString(($req.Split(" "))[1].TrimStart("/"));if(!$p){$p="."};$f=Join-Path (Get-Location) $p;if(Test-Path $f){if((Get-Item $f).PSIsContainer){$h="<html><body><ul>";Get-ChildItem $f|%{$n=$_.Name;if($p -eq "."){$u=$n}else{$u="$p/$n"};$u=$u -replace "\\","/";$h+="<li><a href='/$u'>$n</a></li>"};$h+="</ul></body></html>";$b=[Text.Encoding]::UTF8.GetBytes($h);$hd="HTTP/1.1 200 OK`r`nContent-Type: text/html`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)}else{$b=[IO.File]::ReadAllBytes($f);$hd="HTTP/1.1 200 OK`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)}}else{$b=[Text.Encoding]::UTF8.GetBytes("404");$hd="HTTP/1.1 404 Not Found`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)};$s.Close();$c.Close()}